# ======================= RENDER =======================
import re as _re
def _slug(s):
    s = _re.sub(r"<[^>]+>", "", s).lower()
    for a, b in (("á","a"),("é","e"),("í","i"),("ó","o"),("ú","u"),("à","a"),("è","e"),("ò","o"),("ï","i"),("ü","u"),("ç","c"),("ñ","n"),("·","")):
        s = s.replace(a, b)
    return _re.sub(r"[^a-z0-9]+", "-", s).strip("-")[:48]

def mat_page(k, lang):
    m = MAT[k]; es = lang == "es"; i = 0 if es else 1
    t = lambda a, b: a if es else b
    toc = "".join(f'<li><a href="#{_slug(s[i])}">{s[i]}</a></li>' for s in m["secs"])
    body = (f'<div class="claro"><span class="label">{t("En 30 segundos", "En 30 segons")}</span><p>{m["resumen"][i]}</p></div>'
            + f'<nav class="toc" aria-label="{t("En esta página", "En aquesta pàgina")}"><span class="label">{t("En esta página", "En aquesta pàgina")}</span><ol>{toc}</ol></nav>'
            + "".join(f'<h2 id="{_slug(s[i])}">{s[i]}</h2>{s[2 + i]}' for s in m["secs"])
            + f'<p class="disc">{t("Información general, no asesoramiento. Para un caso concreto, consulta con un profesional o con el servicio público correspondiente.", "Informació general, no assessorament. Per a un cas concret, consulta un professional o el servei públic corresponent.")}</p>'
            + vig(lang, m["fuente"]))
    dl = "".join(f'<dt>{d[0 + i]}</dt><dd>{d[2 + i]}</dd>' for d in m["datos"])
    rel = [f'<a href="{{{c[0]}}}">{c[1 + i]}</a>' for c in m["contratos"]]
    ext = [f'<a href="{{{c[0]}}}">{c[1 + i]}</a>' for c in m["extra"]]
    side = (box(t("En Catalunya", "A Catalunya"), f'<p>{m["cat"][i]}</p>', "box cc")
            + box(t("Datos clave", "Dades clau"), f'<dl>{dl}</dl>')
            + (box(t("Modelos gratuitos", "Models gratuïts"), ul(rel)) if rel else "")
            + (box(t("Te puede servir", "Et pot servir"), ul(ext + [f'<a href="{{materias}}">{t("Todas las materias", "Totes les matèries")}</a>'])) ))
    return ficha(t("Materia", "Matèria"), m["nom"][i], m["lead"][i], [], body, side)

for _k, _m in MAT.items():
    ROUTES[_k] = _m["rutas"]
    PARENT[_k] = "materias"
    PAGES[_k] = {L: dict(title=_m["nom"][0 if L == "es" else 1] + (": guía práctica" if L == "es" else ": guia pràctica"),
                          desc=_m["lead"][0 if L == "es" else 1],
                          crumbs=[("materias", "Materias" if L == "es" else "Matèries")], html=mat_page(_k, L)) for L in ("es", "ca")}

# Todas las materias enlazan a su página
_MK = {"Familia": "familia", "Família": "familia", "Sucesiones": "sucesiones", "Successions": "sucesiones", "Consumo": "consumo", "Consum": "consumo",
       "Autónomos y empresas": "autonomos", "Autònoms i empreses": "autonomos", "Fiscalidad": "fiscalidad", "Fiscalitat": "fiscalidad",
       "Seguridad Social": "segsocial", "Seguretat Social": "segsocial", "Extranjería": "extranjeria", "Estrangeria": "extranjeria",
       "Administración": "administracion", "Administració": "administracion", "Protección de datos": "datos", "Protecció de dades": "datos"}
def _link_mats(html, lang):
    pr = f'<span class="var" style="color:var(--muted)">{"Próximamente" if lang == "es" else "Properament"}</span>'
    def f(mm):
        k = _MK.get(mm.group(1))
        if not k:
            return mm.group(0)
        inner = mm.group(0)[len('<div class="mat">'):-len("</div>")].replace(pr, "")
        return f'<a class="mat" href="{{{k}}}">{inner}</a>'
    return _re.sub(r'<div class="mat"><b>([^<]+)</b>.*?</div>', f, html, flags=_re.S)

# Guías destacadas en portada y en Materias
def _guias(lang):
    es = lang == "es"; t = lambda a, b: a if es else b
    g = [("jubilacion", t("Cómo pedir la jubilación", "Com demanar la jubilació"), t("Edad, pensión y solicitud paso a paso.", "Edat, pensió i sol·licitud pas a pas.")),
         ("nomina", t("Cómo leer tu nómina", "Com llegir la teva nòmina"), t("Cada línea explicada con un ejemplo.", "Cada línia explicada amb un exemple.")),
         ("segsocial", t("Bajas, paro y prestaciones", "Baixes, atur i prestacions"), t("Cuánto cobras y cómo pedirlo.", "Quant cobres i com demanar-ho.")),
         ("familia", t("Divorcio y custodia", "Divorci i custòdia"), t("Pasos, pensiones y plan de parentalidad.", "Passos, pensions i pla de parentalitat.")),
         ("sucesiones", t("Herencias y testamento", "Herències i testament"), t("Qué hacer cuando fallece un familiar.", "Què fer quan mor un familiar.")),
         ("fiscalidad", t("La declaración de la renta", "La declaració de la renda"), t("Plazos, tramos e impuestos de la vivienda.", "Terminis, trams i impostos de l'habitatge."))]
    return ('<div class="guias">' + "".join(f'<a class="guia" href="{{{k}}}"><b>{a}</b><span>{b}</span></a>' for k, a, b in g) + '</div>')

for _pid, _p in PAGES.items():
    for L in ("es", "ca"):
        if L in _p and "html" in _p[L]:
            _p[L]["html"] = _link_mats(_p[L]["html"], L)
for L in ("es", "ca"):
    es = L == "es"
    blk = (f'<div class="home-block"><div class="wrap"><h2>{"Guías prácticas" if es else "Guies pràctiques"}</h2>'
           f'<p>{"Las dudas más consultadas, explicadas paso a paso." if es else "Els dubtes més consultats, explicats pas a pas."}</p>{_guias(L)}</div></div>')
    h = PAGES["home"][L]["html"]
    mk = f'<div class="home-block"><div class="wrap"><h2>{"Materias" if es else "Matèries"}</h2>'
    if mk in h:
        PAGES["home"][L]["html"] = h.replace(mk, blk + mk, 1)
    hm = PAGES["materias"][L]["html"]
    PAGES["materias"][L]["html"] = hm.replace('<div class="mats">', f'<h2 class="sec">{"Guías más consultadas" if es else "Guies més consultades"}</h2>{_guias(L)}<h2 class="sec">{"Todas las materias" if es else "Totes les matèries"}</h2><div class="mats">', 1)
